# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMF-000001",
    "name": "Pierre",
    "kind": "first-name",
    "meaning": "Pierre is a masculine given name in French. Meaning: Stone. From Greek petros; the French form of Peter."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Pie")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

